/**
 * Central image register. Every photograph the site shows is listed here with where it came from, so that
 * captions and alt text can never present an illustrative image as a real APEX facility, event or person.
 * Outputs are generated by scripts/optimize-images.mjs; keep widths in sync with that script.
 */
export type Provenance =
  /** Supplied by ClearMeat; documents real ClearMeat work. */
  | 'authentic'
  /** AI-generated concept for explaining a technology. Always labelled "Illustrative" on the page. */
  | 'illustrative';

type ImageSet = {
  widths: number[];
  width: number;
  height: number;
  fallback: 'jpg' | 'png';
  dir: 'photos' | 'apex';
  provenance: Provenance;
  /** Original file, for the asset register. */
  source: string;
};

