export const isIllustrative = (id: string) => images[id]?.provenance === 'illustrative';

export function srcSet(id: string, format: string) {
  const set = images[id];
  return set.widths.map((w) => `/images/${set.dir}/${id}-${w}.${format} ${w}w`).join(', ');
}

export function fallbackSrc(id: string) {
  const set = images[id];
  return `/images/${set.dir}/${id}-${set.widths[set.widths.length - 1]}.${set.fallback}`;
}
